            if (static_cast<int>(tokenBuilder.length()) > maxLengthFound) {
                maxLengthFound = tokenBuilder.length();
            }
            tokenBuilder.clear();
        } else if (ch == ')') {
            insideParentheses = false;
            if (!tokenBuilder.empty()) {
                collectedTokens.push_back(tokenBuilder);
                tokenBuilder.clear();
            }
        } else if (std::isalpha(static_cast<unsigned char>(ch))) {
            tokenBuilder += ch;
        } else if (ch == '_') {
            if (insideParentheses) {
                if (!tokenBuilder.empty()) {
                    collectedTokens.push_back(tokenBuilder);
                    tokenBuilder.clear();
                }
            } else {
                if (static_cast<int>(tokenBuilder.length()) > maxLengthFound) {
                    maxLengthFound = tokenBuilder.length();
                }
                tokenBuilder.clear();
            }
        }
    }
    if (static_cast<int>(tokenBuilder.length()) > maxLengthFound) {
        maxLengthFound = tokenBuilder.length();
    }
    std::cout << maxLengthFound << " " << collectedTokens.size() << std::endl;
    return 0;
